using System.Collections;
using System.Diagnostics;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using STS2RitsuLib.Models;
using STS2RitsuLib.Combat.SecondaryResources;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private sealed record TaskBindingMethod(string Path, string DeclaringType, string Signature,
        string Mvid, int Token, string IlSha256, int TargetIdentity, int PatchCount);
    private sealed record TaskResourceCard(string Location, string RuntimeType, bool HasCostContainer,
        int CostResources, bool HasUseContainer, int UseResources);

    private static FieldInfo TaskBindingField(Type type, string name) => type.GetField(name,
        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!;

    private static object[] TaskCloneEntries()
    {
        Type type = typeof(ModelCloneRegistry);
        var gate = (System.Threading.Lock)type.GetField("SyncRoot", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
        using (gate.EnterScope()) return ((IDictionary)type.GetField("Listeners",
            BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!).Values.Cast<object>().ToArray();
    }

    private static TaskBindingMethod[] TaskDelegateBindings(object entry,
        Dictionary<object, int> targetIdentities)
    {
        List<TaskBindingMethod> bindings = [];
        var visited = new HashSet<Delegate>(ReferenceEqualityComparer.Instance);
        void Visit(Delegate callback, string path, int depth)
        {
            if (depth > 8) throw new InvalidOperationException("Unresolved delegate depth.");
            foreach (Delegate item in callback.GetInvocationList())
            {
                if (!visited.Add(item)) throw new InvalidOperationException("Repeated/cyclic delegate source.");
                MethodInfo method = item.Method;
                Patches? patches = Harmony.GetPatchInfo(method);
                int patchCount = patches is null ? 0 : patches.Prefixes.Count + patches.Postfixes.Count
                    + patches.Transpilers.Count + patches.Finalizers.Count;
                int targetId = 0;
                if (item.Target is { } target && !targetIdentities.TryGetValue(target, out targetId))
                {
                    targetId = targetIdentities.Count + 1;
                    targetIdentities.Add(target, targetId);
                }
                byte[] il = method.GetMethodBody()?.GetILAsByteArray()
                    ?? throw new InvalidOperationException("Unresolved method body: " + method);
                bindings.Add(new(path, method.DeclaringType!.AssemblyQualifiedName!, method.ToString()!,
                    method.Module.ModuleVersionId.ToString(), method.MetadataToken,
                    Convert.ToHexString(SHA256.HashData(il)), targetId, patchCount));
                if (item.Target is null) continue;
                for (Type? type = item.Target.GetType(); type != null; type = type.BaseType)
                    foreach (FieldInfo field in type.GetFields(BindingFlags.Instance | BindingFlags.Public
                        | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
                        if (field.GetValue(item.Target) is Delegate nested)
                            Visit(nested, path + "/" + field.Name, depth + 1);
            }
        }
        foreach (string fieldName in new[] { "<Predicate>k__BackingField", "<Listener>k__BackingField" })
            Visit((Delegate)TaskBindingField(entry.GetType(), fieldName).GetValue(entry)!, fieldName, 0);
        return bindings.ToArray();
    }

    private static TaskResourceCard TaskReadSecondaryResourceState(CardModel card, string location)
    {
        bool hasCosts = card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs);
        bool hasUses = card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses);
        int costCount = hasCosts ? ((IDictionary)typeof(SecondaryResourceCostSet).GetField("_costs",
            BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(costs)!).Count : 0;
        int useCount = hasUses ? ((IDictionary)typeof(SecondaryResourcePlayUseSet).GetField("_uses",
            BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(uses)!).Count : 0;
        return new(location, card.GetType().AssemblyQualifiedName!, hasCosts, costCount, hasUses, useCount);
    }

    private static bool TaskHasNoSecondaryLayers(TaskResourceCard card) => card.CostResources == 0 && card.UseResources == 0;

    private Task RunTaskExhaustCloneBindingAsync(CombatState live, Player player)
    {
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string State() => ContinuationStamp.CapturePredicted(player, parent,
            ((SimulatedCombatState)parent.State.CombatState).GetPlayerTurnNumber(player), root.Forecast,
            root.StartTurnNumber).StateText + "\nHISTORY=" + CardContinuationContractHistoryText(parent);
        string parentBefore = State(), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        Stopwatch timer = Stopwatch.StartNew();
        var identities = new Dictionary<object, int>(ReferenceEqualityComparer.Instance);
        object[] entries = TaskCloneEntries();
        if (entries.Length != 1) throw new InvalidOperationException("Unexpected initial clone registrations.");
        object originalEntry = entries[0];
        string modId = (string)TaskBindingField(originalEntry.GetType(), "<ModId>k__BackingField").GetValue(originalEntry)!;
        string listenerId = (string)TaskBindingField(originalEntry.GetType(), "<ListenerId>k__BackingField").GetValue(originalEntry)!;
        if (modId != "com.ritsukage.sts2-RitsuLib" || listenerId != "secondary_resource_costs")
            throw new InvalidOperationException("Unknown initial clone registration.");
        var originalPredicate = (Func<ModelCloneContext, bool>)TaskBindingField(originalEntry.GetType(),
            "<Predicate>k__BackingField").GetValue(originalEntry)!;
        var originalListener = (Action<ModelCloneContext>)TaskBindingField(originalEntry.GetType(),
            "<Listener>k__BackingField").GetValue(originalEntry)!;
        Type bridge = typeof(SecondaryResourceCardExtensions).Assembly.GetType(
            "STS2RitsuLib.Combat.SecondaryResources.SecondaryResourceCloneBridge", true)!;
        MethodInfo expectedInner = bridge.GetMethod("CopySecondaryCosts", BindingFlags.Static | BindingFlags.NonPublic)!;
        TaskBindingMethod[] initialBindings = TaskDelegateBindings(originalEntry, identities);
        bool ExactInner(TaskBindingMethod[] values) => values.Length == 3 && values.All(value => value.PatchCount == 0)
            && values.Count(value => value.Token == expectedInner.MetadataToken
                && value.Mvid == expectedInner.Module.ModuleVersionId.ToString() && value.TargetIdentity == 0) == 1;
        if (!ExactInner(initialBindings)) throw new InvalidOperationException("Initial inner clone delegate is not the reviewed method.");
        string frozenBinding = JsonSerializer.Serialize(initialBindings);
        var cards = new HashSet<CardModel>(ReferenceEqualityComparer.Instance);
        foreach (Player owner in live.Players)
            foreach (CardModel card in owner.Deck.Cards.Concat(owner.PlayerCombatState!.AllCards)) cards.Add(card);
        foreach (CardModel card in ((IEnumerable)typeof(CombatState).GetField("_allCards",
            BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(live)!).Cast<CardModel>()) cards.Add(card);
        foreach (var returning in ((SimulatedCombatState)parent.State.CombatState).PendingReturningCards) cards.Add(returning.Preview);
        TaskResourceCard[] rootCards = cards.Select((card, index) => TaskReadSecondaryResourceState(card, "root/" + index)).ToArray();
        var canonicals = new HashSet<CardModel>(cards.Select(card => ModelDb.GetById<CardModel>(card.Id)), ReferenceEqualityComparer.Instance);
        // These explicit producers were reviewed in the existing direct-generation closure.
        canonicals.Add(ModelDb.Card<Shiv>());
        canonicals.Add(ModelDb.Card<FranticEscape>());
        TaskResourceCard[] canonicalCards = canonicals.Select((card, index) => TaskReadSecondaryResourceState(card, "canonical/" + index)).ToArray();
        if (!rootCards.All(TaskHasNoSecondaryLayers) || !canonicalCards.All(TaskHasNoSecondaryLayers))
            throw new InvalidOperationException("Unexpected existing secondary resource layers.");
        timer.Stop();
        var registry = ModelCloneRegistry.For(modId);
        TaskBindingMethod[] replacedBindings;
        registry.Register<CardModel>(listenerId, (_, _) => { });
        try
        {
            object[] replacedEntries = TaskCloneEntries();
            replacedBindings = TaskDelegateBindings(replacedEntries.Single(), identities);
            if (replacedEntries.Length != entries.Length || ExactInner(replacedBindings)
                || JsonSerializer.Serialize(replacedBindings) == frozenBinding)
                throw new InvalidOperationException("Same-name/count inner replacement was not rejected.");
        }
        finally { registry.Register(listenerId, originalPredicate, originalListener); }
        if (JsonSerializer.Serialize(TaskDelegateBindings(TaskCloneEntries().Single(), identities)) != frozenBinding)
            throw new InvalidOperationException("Original clone binding did not restore.");
        var costSource = (CardModel)player.PlayerCombatState!.Hand.Cards[0].MutableClone();
        const string fixtureResource = "combat_solver_exhaust_binding_fixture";
        SecondaryResourceCostSet sourceCosts = costSource.SecondaryCosts();
        sourceCosts.Set(fixtureResource, 0);
        TaskResourceCard zeroCostLayer = TaskReadSecondaryResourceState(costSource, "detached-zero-layer");
        if (sourceCosts.HasCosts || TaskHasNoSecondaryLayers(zeroCostLayer))
            throw new InvalidOperationException("Zero-cost layer was incorrectly treated as absent.");
        sourceCosts.Set(fixtureResource, 1);
        var costClone = (CardModel)costSource.MutableClone();
        if (!costClone.TryGetSecondaryCosts(out SecondaryResourceCostSet cloneCosts)
            || ReferenceEquals(sourceCosts, cloneCosts) || cloneCosts.ResourceIds.Count != 1)
            throw new InvalidOperationException("Native clone did not copy its secondary cost container.");
        cloneCosts.Clear(fixtureResource);
        if (sourceCosts.ResourceIds.Count != 1 || !TaskHasNoSecondaryLayers(TaskReadSecondaryResourceState(costClone, "detached-cleared-clone")))
            throw new InvalidOperationException("Cost clone shared the source list/dictionary mutation.");
        sourceCosts.Clear(fixtureResource);
        if (State() != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore
            || !cards.All(card => TaskHasNoSecondaryLayers(TaskReadSecondaryResourceState(card, "after-root"))))
            throw new InvalidOperationException("Binding audit mutated its parent/live/root layers.");
        _completedChecks.Add("ExhaustCloneBinding:RealInnerDelegateMvidTokenIL:SameNameCountReplacementRejected:RootDeckAllPilesFloatingReturningCanonicalShivFrantic:ZeroLayerRejected:NativeCloneCostIsolation:FullStateHistoryRngParentLive");
        _completedChecks.Add("TASK_EXHAUST_CLONE_BINDING " + JsonSerializer.Serialize(new { initialBindings,
            replacedBindings, rootCards, canonicalCards, zeroCostLayer, sameNameCountReplacementRejected = true,
            nativeCostCloneDistinct = true, sourceUnaffectedByCloneClear = true,
            captureMilliseconds = timer.Elapsed.TotalMilliseconds, actualPrunes = 0,
            cloneBindingComponentVerified = true, isWholeOrderCertificate = false }));
        return Task.CompletedTask;
    }
}

